CREATE TABLE "citas" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "citas_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"rut" text NOT NULL,
	"sede" text NOT NULL,
	"fecha" text NOT NULL,
	"hora" text NOT NULL,
	"estado" text DEFAULT 'agendada',
	"fecha_creacion" timestamp with time zone DEFAULT now(),
	CONSTRAINT "citas_estado_check" CHECK ("citas"."estado" IN ('agendada', 'cancelada', 'realizada'))
);
