CREATE TABLE "ficha_medica" (
	"rut" text PRIMARY KEY NOT NULL,
	"presion_arterial" text,
	"frecuencia_cardiaca" integer,
	"peso" real,
	"estado_clinico" text,
	"tipo_sangre" text,
	"fecha_elegibilidad" text,
	"observaciones" text,
	"fecha_actualizacion" timestamp with time zone DEFAULT now(),
	CONSTRAINT "ficha_medica_estado_clinico_check" CHECK ("ficha_medica"."estado_clinico" IS NULL OR "ficha_medica"."estado_clinico" IN ('listo para donar', 'Diferido'))
);
